# t12: AI website builder (text+voice), edit-by-command, SEO/AEO/GEO suite, off-page, AI tools, metering
from playwright.sync_api import sync_playwright
import json
res=[];errs=[]
def ok(n,c,x=''):res.append((n,bool(c)));print('PASS' if c else 'FAIL',n,'::',str(x)[:140])
def go(pg,h):pg.evaluate(f"location.hash='{h}';route()");pg.wait_for_timeout(300)
def cl(pg,x):pg.click(f'[data-x="{x}"]');pg.wait_for_timeout(300)
def M(pg):return pg.inner_text('#main')
with sync_playwright() as p:
  b=p.chromium.launch();pg=b.new_page(viewport={'width':1400,'height':900})
  pg.on('pageerror',lambda e:errs.append(str(e)[:200]));pg.on('console',lambda m:m.type=='error' and errs.append(m.text[:200]))
  pg.on('dialog',lambda d:d.accept())
  pg.goto('file:///workspace/sellora/sellora.html');pg.wait_for_timeout(800)
  go(pg,'ai-builder');ok('nav AI builder group',all(k in pg.inner_text('#nav') for k in ['SEO / AEO / GEO','Off-page SEO','AI tools']))
  ok('builder page','Describe your store' in M(pg) and 'Speak' in M(pg))
  # voice unsupported in headless → graceful
  pg.evaluate("window.webkitSpeechRecognition=undefined;window.SpeechRecognition=undefined");cl(pg,'m12mic:m12prompt');ok('voice fallback message','Voice' in pg.inner_text('#m12vstat') or 'Listening' in pg.inner_text('#m12vstat'),pg.inner_text('#m12vstat'))
  # mock Web Speech API and speechSynthesis
  pg.evaluate("""window._spoken=[];window.SpeechSynthesisUtterance=function(t){this.text=t};Object.defineProperty(window,'speechSynthesis',{configurable:true,value:{cancel(){},speak(u){window._spoken.push(u.text)}}});
  window.webkitSpeechRecognition=function(){this.lang='';var s=this;this.start=function(){setTimeout(function(){s.onresult({results:[[{transcript:'Women lawn clothing brand in Lahore'}]]});s.onend()},50)};this.stop=function(){}}""")
  go(pg,'ai-builder');cl(pg,'m12mic:m12prompt');pg.wait_for_timeout(200)
  ok('classic builder kept',pg.evaluate("typeof V['ai-builder-classic']")=='function')
  ok('voice fills prompt',pg.input_value('#m12prompt')=='Women lawn clothing brand in Lahore')
  n0=pg.evaluate("S.products.length");u0=pg.evaluate("+(S.use9&&S.use9.ai)||0")
  cl(pg,'m12build');t=M(pg)
  ok('preview rendered',pg.query_selector('#m12prev') is not None and 'Embroidered Lawn Kurta' in t,t[:200])
  ok('fashion niche detected',pg.evaluate("S.ai12.site.niche")=='fashion')
  ok('4 draft products added',pg.evaluate("S.products.length")==n0+4 and pg.evaluate("S.products.slice(-1)[0].status")=='Draft')
  ok('pages, menus, policies, blog applied',pg.evaluate("S.pages.some(p=>p.h==='contact')&&S.menusList.some(m=>m.handle==='footer')&&!!S.pol.shipping&&S.blogPosts.some(b=>b.author==='AI')"))
  ok('25 AI credits metered',pg.evaluate("+S.use9.ai")==u0+25,pg.evaluate("S.use9.ai"))
  ok('spoken reply',any('website' in s for s in pg.evaluate("window._spoken")))
  pg.fill('#m12cmd','make header black');cl(pg,'m12edit');ok('edit header black',pg.evaluate("S.ai12.theme.settings.header.bg")=='#000000' and 'Done' in pg.inner_text('#m12edres'))
  pg.fill('#m12cmd','add FAQ section');cl(pg,'m12edit');ok('edit add faq section',pg.evaluate("S.ai12.theme.sections.home.some(s=>s.type==='faq')"))
  pg.fill('#m12cmd','change headline to Eid Sale');cl(pg,'m12edit');ok('edit headline','Eid Sale' in pg.inner_text('#m12prev'))
  pg.fill('#m12cmd','remove newsletter section');cl(pg,'m12edit');ok('edit remove section',not pg.evaluate("S.ai12.theme.sections.home.some(s=>s.type==='newsletter')"))
  pg.fill('#m12cmd','make it green');cl(pg,'m12edit');ok('unknown command explained',"didn't understand" in pg.inner_text('#m12edres'))
  pg.fill('#m12cmd','make background red');cl(pg,'m12edit');ok('theme colours mirrored',pg.evaluate("S.themes[0].bg")=='#C0392B')
  pg.fill('#m12cmd','make background white');cl(pg,'m12edit')
  # SEO
  go(pg,'seo-suite');pg.evaluate("S.products[0].desc='See <a href=\"/products/does-not-exist\">old</a>';S.products[0].seo={};save()");go(pg,'seo-suite')
  s0=pg.evaluate("m12audit().score");ok('audit score & issues','SEO health' in M(pg) and pg.evaluate("m12audit().issues.length")>0,s0)
  ok('broken link detected',pg.evaluate("m12audit().issues.some(i=>i.id==='br:/products/does-not-exist')"))
  ok('CWV hints','LCP' in M(pg) and 'CLS' in M(pg))
  cl(pg,'m12fixall');s1=pg.evaluate("m12audit().score");ok('fix all raises score',s1>s0,f'{s0}->{s1}')
  ok('redirect created for broken link',pg.evaluate("S.ai12.red.some(r=>r.from==='/products/does-not-exist'&&r.code===301)"))
  ok('meta written',pg.evaluate("!!S.products[0].seo.title&&S.products[0].seo.title.length<=60&&S.products[0].seo.desc.length<=155"))
  cl(pg,'m12tab:schema');ld=json.loads(pg.input_value('#m12ld'));types={x['@type'] for x in ld}
  ok('JSON-LD types',{'Organization','WebSite','LocalBusiness','Product','BreadcrumbList','FAQPage'}<=types,types)
  ok('product offer has currency',any(x.get('offers',{}).get('priceCurrency') for x in ld))
  ok('sitemap with hreflang','hreflang="ur"' in pg.input_value('#m12sm'))
  ok('robots allows AI bots','GPTBot' in pg.input_value('#m12rb'))
  ok('llms.txt','## Products' in pg.input_value('#m12llms'))
  ok('head tags canonical/OG/twitter',all(k in pg.input_value('#m12head') for k in ['canonical','og:title','twitter:card','hreflang']))
  cl(pg,'m12tab:aeo');pg.fill('#m12topic','lawn suits');cl(pg,'m12aeo');ok('AEO FAQ','best lawn suits' in pg.inner_text('#m12faq'))
  cl(pg,'m12geo');ok('GEO content','Entity summary' in pg.inner_text('#m12geoc'))
  cl(pg,'m12tab:keywords');pg.fill('#m12seed','lawn suit');cl(pg,'m12kw');ok('keywords clustered','lawn suit price in pakistan' in pg.inner_text('#m12kwc'))
  ok('content gaps','Content gaps' in M(pg) and 'Blog post' in M(pg))
  cl(pg,'m12cal');ok('8-week calendar',pg.evaluate("S.ai12.cal.length")==8)
  cl(pg,'m12tab:links');pg.fill('#m12rf','/a');pg.fill('#m12rt','/b');cl(pg,'m12radd');pg.fill('#m12rf','/b');pg.fill('#m12rt','/a');cl(pg,'m12radd')
  ok('redirect loop blocked','loop' in pg.inner_text('#m12rerr'))
  ok('internal links','Internal link suggestions' in M(pg))
  cl(pg,'m12tab:index');cl(pg,'m12sub:indexnow');ok('IndexNow simulated','IndexNow' in pg.inner_text('#m12subres'))
  cl(pg,'m12rank');ok('rank positions',pg.evaluate("S.ai12.kw.every(k=>k.ranks.length===1)") and '#' in pg.inner_text('#m12rk'))
  # off-page
  go(pg,'seo-offpage');ok('citations list','Google Business Profile' in M(pg) and 'Daraz' in M(pg))
  pg.select_option('select[data-c="Google Business Profile"]','live');pg.wait_for_timeout(300);ok('citation status saved',pg.evaluate("S.ai12.cit['Google Business Profile']")=='live' and '1/20 live' in M(pg))
  cl(pg,'m12out');ok('outreach','Collaboration idea' in pg.input_value('#m12outtpl'))
  cl(pg,'m12gbp');ok('GBP helper','Verify the profile' in pg.inner_text('#m12gbpc'))
  pg.fill('#m12soc','Eid sale');cl(pg,'m12social');ok('social posts',all(k in pg.inner_text('#m12socc') for k in ['facebook','instagram','tiktok']))
  # AI tools
  go(pg,'ai-tools');u1=pg.evaluate("+S.use9.ai");cl(pg,'m12desc');ok('EN/UR/AR descriptions',pg.query_selector_all('.m12lang[dir="rtl"]').__len__()==2 and 'کیش' in pg.inner_text('#m12descc'))
  ok('describe metered 3',pg.evaluate("+S.use9.ai")==u1+3)
  cl(pg,'m12alt');ok('alt text','Caption' in pg.inner_text('#m12altc'))
  pg.fill('#m12rv','Late delivery, bad');pg.select_option('#m12rr','1');cl(pg,'m12rep');ok('review reply apologetic','sorry' in pg.inner_text('#m12reply'))
  pg.fill('#m12goal','Eid sale 20% off');cl(pg,'m12camp');ok('WhatsApp campaign','STOP' in pg.input_value('#m12campo'))
  pg.fill('#m12url','https://x.pk/p');cl(pg,'m12comp');ok('competitor placeholder','placeholder' in pg.inner_text('#m12compc'))
  pg.fill('#m12q','Do you deliver to Multan?');cl(pg,'m12ask');ok('chatbot answers delivery','working days' in pg.inner_text('#m12chat'))
  ok('usage log','ai.describe' in M(pg))
  # trial ends / limit: on free plan quota exhausted → blocked
  pg.evaluate("S.sub9.plan='starter';S.sub9.status='active';S.use9.ai=30;save()");go(pg,'ai-tools');ok('quota blocks AI when exhausted',pg.evaluate("window.meter9('ai',1)")==False);pg.click('#xok') if pg.query_selector('#xok') else None
  go(pg,'seo-suite');pg.set_viewport_size({'width':390,'height':800});go(pg,'seo-suite');ok('mobile no overflow',pg.evaluate("document.documentElement.scrollWidth<=400"),pg.evaluate("document.documentElement.scrollWidth"))
  ok('no console errors',not errs,errs)
  b.close()
print(sum(1 for r in res if r[1]),'/',len(res),'passed');json.dump(res,open('t12-results.json','w'))
